def get_lang_map(lang: str, prefix: str = None) -> dict:
    """Return merged translations for a language.

    Merge order (fallback):
      1) German (base)
      2) English
      3) requested language

    If `prefix` is given, only keys starting with that prefix are returned.
    """
    lang = normalize_lang(lang)
    merged = {}
    try:
        merged.update(_I18N.get("de", {}))
        merged.update(_I18N.get("en", {}))
        merged.update(_I18N.get(lang, {}))
    except Exception:
        merged = dict(_I18N.get(lang, {}) or {})
    if prefix:
        try:
            merged = {k: v for (k, v) in merged.items() if str(k).startswith(prefix)}
        except Exception:
            pass
    return merged



def _platform_supports_emoji() -> bool:
    """Check if the current platform can render emoji in tkinter."""
    import sys
    if sys.platform.startswith("darwin"):
        return True
    if sys.platform == "win32":
        try:
            ver = sys.getwindowsversion()
            return ver.major >= 10
        except Exception:
            return False
    return False


_EMOJI_SUPPORTED: bool | None = None


def _strip_emoji(text: str) -> str:
    """Remove emoji from text on platforms that can't render them in tkinter."""
    global _EMOJI_SUPPORTED
    if _EMOJI_SUPPORTED is None:
        _EMOJI_SUPPORTED = _platform_supports_emoji()
    if _EMOJI_SUPPORTED:
        return text
    import re
    return re.sub(
        r'[\U0001F300-\U0001FAFF\U00002600-\U000027BF\U0000FE00-\U0000FE0F'
        r'\U0001F900-\U0001F9FF\U00002702-\U000027B0\U0000231A-\U0000231B'
        r'\U00002328\U000023CF\U000023E9-\U000023F3\U000023F8-\U000023FA'
        r'\U0000200D\U00002B05-\U00002B07\U00002B1B-\U00002B1C\U00002B50'
        r'\U00002B55\U00003030\U0000303D\U00003297\U00003299]+', '', text
    ).strip()


def t(lang: str, key: str, *, strip_emoji: bool = False, **kwargs: object) -> str:
    """Translate a key for a language.

    Fallback order:
      1) requested language
      2) English
      3) German
      4) key itself

    If *strip_emoji* is True, emoji are removed on platforms that cannot
    render them in tkinter (Linux, older Windows).
    """
    lang = normalize_lang(lang)
    s = (
        (_I18N.get(lang, {}) or {}).get(key)
        or (_I18N.get("en", {}) or {}).get(key)
        or (_I18N.get("de", {}) or {}).get(key)
        or key
    )
    try:
        result = str(s).format(**kwargs)
    except Exception:
        result = str(s)
    return _strip_emoji(result) if strip_emoji else result


def resolve_name(lang: str, name: str) -> str:
    """Translate *name* when it is itself a translation key, else return it.

    Demo devices carry keys like ``demo.device.house_3p`` as their name so the
    generated house is labelled in the user's language.  Anything a user typed
    is passed through untouched — a real device called "Keller" stays "Keller".
    """
    n = str(name or "")
    if "." not in n or " " in n:
        return n
    out = t(lang, n)
    return n if out == n else out


def normalize_lang(lang: str) -> str:
    lang = (lang or "de").lower().strip()
    return lang if lang in LANGS else "de"



