# ── Wochentags- und Monatsnamen ────────────────────────────────────────────
# 🔴 strftime("%A") / ("%B") liefert, was die C-Locale des Containers sagt —
# also Englisch, egal was in der App eingestellt ist. Genau so stand
# "Friday, 25.09.2026" im deutschen Bericht. Reihenfolge wie date.weekday():
# Montag = 0.
_WD_LANG = {
    "en": ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"],
    "de": ["Montag", "Dienstag", "Mittwoch", "Donnerstag", "Freitag", "Samstag", "Sonntag"],
    "es": ["lunes", "martes", "miércoles", "jueves", "viernes", "sábado", "domingo"],
    "fr": ["lundi", "mardi", "mercredi", "jeudi", "vendredi", "samedi", "dimanche"],
    "pt": ["segunda-feira", "terça-feira", "quarta-feira", "quinta-feira", "sexta-feira", "sábado", "domingo"],
    "it": ["lunedì", "martedì", "mercoledì", "giovedì", "venerdì", "sabato", "domenica"],
    "pl": ["poniedziałek", "wtorek", "środa", "czwartek", "piątek", "sobota", "niedziela"],
    "cs": ["pondělí", "úterý", "středa", "čtvrtek", "pátek", "sobota", "neděle"],
    "ru": ["понедельник", "вторник", "среда", "четверг", "пятница", "суббота", "воскресенье"],
}

_WD_KURZ = {
    "en": ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"],
    "de": ["Mo", "Di", "Mi", "Do", "Fr", "Sa", "So"],
    "es": ["lun", "mar", "mié", "jue", "vie", "sáb", "dom"],
    "fr": ["lun", "mar", "mer", "jeu", "ven", "sam", "dim"],
    "pt": ["seg", "ter", "qua", "qui", "sex", "sáb", "dom"],
    "it": ["lun", "mar", "mer", "gio", "ven", "sab", "dom"],
    "pl": ["pon", "wt", "śr", "czw", "pt", "sob", "niedz"],
    "cs": ["po", "út", "st", "čt", "pá", "so", "ne"],
    "ru": ["пн", "вт", "ср", "чт", "пт", "сб", "вс"],
}

_MON_LANG = {
    "en": ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"],
    "de": ["Januar", "Februar", "März", "April", "Mai", "Juni", "Juli", "August", "September", "Oktober", "November", "Dezember"],
    "es": ["enero", "febrero", "marzo", "abril", "mayo", "junio", "julio", "agosto", "septiembre", "octubre", "noviembre", "diciembre"],
    "fr": ["janvier", "février", "mars", "avril", "mai", "juin", "juillet", "août", "septembre", "octobre", "novembre", "décembre"],
    "pt": ["janeiro", "fevereiro", "março", "abril", "maio", "junho", "julho", "agosto", "setembro", "outubro", "novembro", "dezembro"],
    "it": ["gennaio", "febbraio", "marzo", "aprile", "maggio", "giugno", "luglio", "agosto", "settembre", "ottobre", "novembre", "dicembre"],
    "pl": ["styczeń", "luty", "marzec", "kwiecień", "maj", "czerwiec", "lipiec", "sierpień", "wrzesień", "październik", "listopad", "grudzień"],
    "cs": ["leden", "únor", "březen", "duben", "květen", "červen", "červenec", "srpen", "září", "říjen", "listopad", "prosinec"],
    "ru": ["январь", "февраль", "март", "апрель", "май", "июнь", "июль", "август", "сентябрь", "октябрь", "ноябрь", "декабрь"],
}


def weekday_name_local(lang: str, d, short: bool = False) -> str:
    """Der Wochentag von *d* in der Sprache (Montag = 0)."""
    quelle = _WD_KURZ if short else _WD_LANG
    namen = quelle.get(normalize_lang(lang)) or quelle["en"]
    try:
        return namen[d.weekday()]
    except Exception:
        return ""


def weekday_names_local(lang: str, short: bool = True) -> list:
    """Alle sieben Wochentage, Montag zuerst."""
    quelle = _WD_KURZ if short else _WD_LANG
    return list(quelle.get(normalize_lang(lang)) or quelle["en"])


def month_name_local(lang: str, monat: int) -> str:
    """Der Monatsname (1 = Januar) in der Sprache."""
    namen = _MON_LANG.get(normalize_lang(lang)) or _MON_LANG["en"]
    try:
        return namen[int(monat) - 1]
    except Exception:
        return ""


